SourceCode.Declaration:
/// <summary>
/// A store's stock count in the Stock count control center: the master journal holding one
/// staging journal per counter (HSMobileOpsCountStage), each with its counted lines
/// (HSMobileOpsCountStageLine). Opened by the first counter who starts counting the store - a
/// free store count, or one counting journal (SourceJournalId) - and Transferred once the
/// supervisor moves the reviewed counts into a D365FO counting journal. Counters, lines and
/// duplicates are stored figures kept current by HSMobileOpsCountControl::refresh - display
/// methods render blank on this environment's forms.
/// </summary>
public class HSMobileOpsCountMaster extends common
{
}

Method.Source:
public static HSMobileOpsCountMaster find(str _masterId, boolean _forUpdate = false)
{
    HSMobileOpsCountMaster master;

    master.selectForUpdate(_forUpdate);
    if (_masterId)
    {
        select firstonly master where master.MasterId == _masterId;
    }
    return master;
}
